    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_14",
      "quote": "17 articles were excluded due to wrong outcome ( n ¼ 6), wrong population ( n ¼ 5), wrong study design ( n ¼ 4), duplicate data ( n ¼ 1) and for being preprint ( n ¼ 1).",
      "reason": "Although exclusions include “wrong outcome,” the evidence does not distinguish exclusion because outcomes were not measured versus exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
